"use strict";(self.webpackChunkpf_1_ee=self.webpackChunkpf_1_ee||[]).push([[5658],{7360:(e,n,a)=>{a.r(n),a.d(n,{assets:()=>h,contentTitle:()=>o,default:()=>d,frontMatter:()=>r,metadata:()=>i,toc:()=>l});const i=JSON.parse('{"id":"srd/classes/core/rogue/archetypes/ninja","title":"Ninja","description":"Weapon and Armor Proficiency","source":"@site/docs/srd/classes/core/rogue/archetypes/ninja.md","sourceDirName":"srd/classes/core/rogue/archetypes","slug":"/srd/classes/core/rogue/archetypes/ninja","permalink":"/PF1EE/docs/srd/classes/core/rogue/archetypes/ninja","draft":false,"unlisted":false,"editUrl":"https://github.com/massacresIV/PF1EE/tree/main/docs/srd/classes/core/rogue/archetypes/ninja.md","tags":[],"version":"current","frontMatter":{},"sidebar":"srdSidebar","previous":{"title":"Rogue Archetypes","permalink":"/PF1EE/docs/srd/classes/core/rogue/archetypes/"},"next":{"title":"Rowdy Rogue","permalink":"/PF1EE/docs/srd/classes/core/rogue/archetypes/rowdy-rogue"}}');var s=a(4848),t=a(8453);const r={},o="Ninja",h={},l=[{value:"Weapon and Armor Proficiency",id:"weapon-and-armor-proficiency",level:2},{value:"AC Bonus (Ex)",id:"ac-bonus-ex",level:2},{value:"Ki Pool (Su)",id:"ki-pool-su",level:2},{value:"Poison Use",id:"poison-use",level:2},{value:"Ninja Tricks",id:"ninja-tricks",level:2},{value:"No Trace (Ex)",id:"no-trace-ex",level:2},{value:"Master Ninja Tricks",id:"master-ninja-tricks",level:2},{value:"Hidden Master (Su)",id:"hidden-master-su",level:2}];function c(e){const n={admonition:"admonition",blockquote:"blockquote",em:"em",h1:"h1",h2:"h2",header:"header",hr:"hr",li:"li",p:"p",strong:"strong",ul:"ul",...(0,t.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(n.header,{children:(0,s.jsx)(n.h1,{id:"ninja",children:"Ninja"})}),"\n",(0,s.jsx)(n.h2,{id:"weapon-and-armor-proficiency",children:"Weapon and Armor Proficiency"}),"\n",(0,s.jsx)(n.p,{children:"Ninja are proficient with all simple weapons, plus the kama, katana, kusarigama, nunchaku, sai, shortbow, short sword, shuriken, siangham, and wakizashi. They are not proficient with any type of armor or shield."}),"\n",(0,s.jsx)("u",{children:"This alters the rogue\u2019s weapon proficiencies."}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.h2,{id:"ac-bonus-ex",children:"AC Bonus (Ex)"}),"\n",(0,s.jsx)(n.p,{children:"A Ninja is highly trained at dodging blows, and she has a sixth sense that lets her avoid even unanticipated attacks. When unarmored and unencumbered, a Ninja adds her Wisdom modifier (minimum 0) to her AC and her CMD. A Ninja with levels in another class only adds 1 point of his Wisdom bonus (if any) per Ninja class level. In addition, a Ninja gains a +1 bonus to AC and CMD at 4th level. This bonus increases by 1 for every four Ninja levels thereafter, up to a maximum of +5 at 20th level."}),"\n",(0,s.jsx)(n.p,{children:"These bonuses to AC apply even against touch attacks or when the Ninja is flat-footed. She loses these bonuses when she is immobilized or helpless, when she wears any armor, when she carries a shield, or when she carries a medium or heavy load."}),"\n",(0,s.jsx)(n.p,{children:"This counts as the monk ability of the same name, and the sacred Ninja\u2019s rogue levels stack with monk levels for determining the benefits."}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.h2,{id:"ki-pool-su",children:"Ki Pool (Su)"}),"\n",(0,s.jsx)(n.p,{children:"At 1st level, a Ninja gains a pool of ki points, supernatural energy she can use to accomplish amazing feats. The number of points in the Ninja\u2019s ki pool is equal to 1/2 her Ninja level + her Wisdom modifier. As long as she has at least 1 point in her ki pool, she treats any Acrobatics skill check made to jump as if she had a running start. At 10th level, she also reduces the DC of Acrobatics skill checks made to jump by 1/2 (although she still cannot move farther than her speed allows)."}),"\n",(0,s.jsx)(n.p,{children:"By spending 1 point from her ki pool, a Ninja can do one of the following:"}),"\n",(0,s.jsxs)(n.ul,{children:["\n",(0,s.jsx)(n.li,{children:"Make one additional attack at her highest attack bonus when making a full attack. This bonus attack stacks with all bonus attacks from other sources, such as those from haste and similar effects."}),"\n",(0,s.jsx)(n.li,{children:"Increase her speed by 20 feet for 1 round."}),"\n",(0,s.jsx)(n.li,{children:"Give herself a +4 insight bonus on Stealth checks for 1 round."}),"\n"]}),"\n",(0,s.jsx)(n.p,{children:"A Ninja can gain additional powers that consume points from her ki pool by selecting certain Rogue Talents. Whenever a rogue talent or advanced talent would require or expend points from a guile pool, the Ninja instead uses her ki pool. For all purposes related to rogue talents and abilities, her ki pool counts as a guile pool."}),"\n",(0,s.jsx)(n.p,{children:"The ki pool is replenished each morning after 8 hours of rest or meditation; these hours do not need to be consecutive. If the Ninja possesses levels in another class that grants points to a ki pool, Ninja levels stack with the levels of that class to determine the total number of ki points in the combined pool, but only one ability score modifier is added to the total. The choice of which score to use is made when the second class ability is gained, and once made, the choice is set. The Ninja can now use ki points from this pool to power the abilities of every class she possesses that grants a ki pool."}),"\n",(0,s.jsx)("u",{children:"This ability replaces Guile."}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.h2,{id:"poison-use",children:"Poison Use"}),"\n",(0,s.jsxs)(n.p,{children:["At 1st level, a Ninja gains ",(0,s.jsx)(n.em,{children:"Poison Use"})," as a bonus feat, even if she does not meet the prerequisites."]}),"\n",(0,s.jsx)("u",{children:"This ability replaces Trapfinding."}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.h2,{id:"ninja-tricks",children:"Ninja Tricks"}),"\n",(0,s.jsx)(n.p,{children:"A Ninja can select from any of the following ninja tricks, in addition to general rogue talents."}),"\n",(0,s.jsxs)(n.ul,{children:["\n",(0,s.jsxs)(n.li,{children:["\n",(0,s.jsx)(n.p,{children:"Acrobatic Master (Su): A ninja with this trick can expend 1 ki point from her ki pool as a swift action to grant herself a +20 bonus on one Acrobatics check of her choice made before the start of her next turn."}),"\n"]}),"\n",(0,s.jsxs)(n.li,{children:["\n",(0,s.jsx)(n.p,{children:"Deflect Arrows: A ninja with this trick gains the Deflect Arrows feat as a bonus feat. The ninja must have the Unarmed Combatant feat before taking this trick."}),"\n"]}),"\n",(0,s.jsxs)(n.li,{children:["\n",(0,s.jsx)(n.p,{children:"Feather Fall (Su): As an immediate action, a ninja with this trick can slow her descent as if using feather fall. This ability uses her ninja level as the caster level. Each use of this ability uses up 1 ki point."}),"\n"]}),"\n",(0,s.jsxs)(n.li,{children:["\n",(0,s.jsx)(n.p,{children:"Flurry of Stars (Ex): A ninja with this trick can expend 1 ki point from her ki pool as a swift action before she makes a full-attack attack with shuriken. During that attack, she can throw two additional shuriken at her highest attack bonus, but all of her shuriken attacks are made at a \u20132 penalty, including the two extra attacks."}),"\n"]}),"\n",(0,s.jsxs)(n.li,{children:["\n",(0,s.jsx)(n.p,{children:"Forgotten Trick (Ex): A ninja can recall one trick taught to her by her ancient masters. When she uses this ability, she selects one ninja trick (not a master trick or rogue talent) that she does not know and can use that ninja trick for a number of rounds equal to her level. She must pay any ki costs associated with the trick as normal. Using this ability expends 2 ki points from her ki pool, plus the ki cost of the trick she chooses."}),"\n"]}),"\n",(0,s.jsxs)(n.li,{children:["\n",(0,s.jsx)(n.p,{children:"Herbal Compound (Ex): A ninja with this trick can consume specially prepared herbs to strengthen her mind. The ninja can spend 1 ki point and smoke, eat, or inject an herbal compound as a move action. The ninja takes a \u20132 penalty to AC and on Reflex saves but gains a +4 alchemical bonus on Will saves for 10 minutes per ninja level."}),"\n"]}),"\n",(0,s.jsxs)(n.li,{children:["\n",(0,s.jsx)(n.p,{children:"Kamikaze (Su): A ninja with this trick strikes without concern for her own well-being. The ninja can spend 1 point from her ki pool to give her unarmed strikes and any weapons she wields the vicious weapon special ability for 1 round per level. The ninja can spend 1 ki point to dismiss this effect."}),"\n"]}),"\n",(0,s.jsxs)(n.li,{children:["\n",(0,s.jsx)(n.p,{children:"Ki Charge (Su): A ninja with this trick can invest a portion of her ki into a single thrown weapon, such as a shuriken, and throw it as a standard action. The thrown weapon explodes on impact in a 5-foot burst, dealing 1d6 points of fire damage plus 1d6 points of fire damage for every four levels of the ninja above 2nd, to a maximum 4d6 at 18th level. Creatures caught in the blast receive a Reflex save to halve the damage. The DC of this save is 10 + 1/2 the ninja\u2019s level + the ninja\u2019s Wisdom modifier. If the thrown weapon hits a creature, that creature takes a \u20132 penalty on the saving throw. If the thrown weapon misses, treat it as a thrown splash weapon. Using this ability expends 1 ki point from her ki pool."}),"\n"]}),"\n",(0,s.jsxs)(n.li,{children:["\n",(0,s.jsx)(n.p,{children:"Ki Venom (Ex): A ninja with this trick knows how to make poisons from innocuous herbs or minerals. Creating ki venom is a full-round action that costs 1 ki point. The poison lasts for 24 hours before becoming inert. The poison deals either Strength or Dexterity damage, chosen when the venom is created. The ninja can spend additional ki as part of the process of creating the ki venom to improve the venom in one or more of the following ways: spend 1 ki point to increase the damage die to a d6, spend 1 ki point to change the ability damage dealt to Intelligence, Wisdom, or Charisma damage, or spend 1 ki point to increase the number of saves required to cure the poison by 1."}),"\n"]}),"\n"]}),"\n",(0,s.jsxs)(n.blockquote,{children:["\n",(0,s.jsxs)(n.admonition,{title:"Ki Venom",type:"note",children:[(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Type"})," poison, injury; ",(0,s.jsx)(n.strong,{children:"Save"})," Fortitude DC = 10 + 1/2 the ninja\u2019s level + her Charisma modifier"]}),(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Frequency"})," 1/round for rounds equal to the ninja\u2019s Charisma modifier."]}),(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Effect"})," 1d4 ability damage (see above); ",(0,s.jsx)(n.strong,{children:"Cure"})," 1 save"]})]}),"\n"]}),"\n",(0,s.jsxs)(n.ul,{children:["\n",(0,s.jsxs)(n.li,{children:["\n",(0,s.jsx)(n.p,{children:"Light Step (Ex): As a full-round action, a ninja with this trick can move up to twice her speed, ignoring difficult terrain. While moving in this way, any surface will support her, no matter how much she weighs. This allows her to move across water, lava, or even the thinnest tree branches. She must end her move on a surface that can support her normally. She cannot move across air in this way, nor can she walk up walls or other vertical surfaces. When moving in this way, she does not take damage from surfaces or hazards that react to being touched, such as lava or caltrops, nor does she need to make Acrobatics checks to avoid falling on slippery or rough surfaces. Finally, when using light steps, the ninja ignores any mechanical traps that use a location-based trigger."}),"\n"]}),"\n",(0,s.jsxs)(n.li,{children:["\n",(0,s.jsx)(n.p,{children:"Shadow Clone (Su): A ninja with this trick can expend 1 ki point from her ki pool as a standard action to create 1d4 shadowy duplicates of herself that conceal her true location. This ability functions as mirror image, using the ninja\u2019s level as her caster level."}),"\n"]}),"\n",(0,s.jsxs)(n.li,{children:["\n",(0,s.jsx)(n.p,{children:"Snatch Arrows: A ninja with this trick gains the Snatch Arrows feat as a bonus feat. The ninja must have the Unarmed Combatant feat and the Deflect Arrows feat before taking this trick."}),"\n"]}),"\n",(0,s.jsxs)(n.li,{children:["\n",(0,s.jsx)(n.p,{children:"Style Master: A ninja with this trick gains a style feat that she qualifies for as a bonus feat."}),"\n"]}),"\n",(0,s.jsxs)(n.li,{children:["\n",(0,s.jsx)(n.p,{children:"Swift Poisoner: A ninja with this trick gains Swift Poisoner as a bonus feat, even if she does not meet the prerequisites."}),"\n"]}),"\n",(0,s.jsxs)(n.li,{children:["\n",(0,s.jsx)(n.p,{children:"Unarmed Combat Training: A ninja with this trick gains Unarmed Combatant as a bonus feat, even if she does not meet the prerequisites."}),"\n"]}),"\n"]}),"\n",(0,s.jsx)(n.admonition,{title:"Changes",type:"info",children:(0,s.jsx)(n.p,{children:"Updated from Improved Unarmed Strike to Unarmed Combatant."})}),"\n",(0,s.jsxs)(n.ul,{children:["\n",(0,s.jsx)(n.li,{children:"Vanishing Trick (Su): A ninja with this trick can expend 1 ki point from her ki pool as a swift action to disappear for 1 round per level. This ability functions as invisibility."}),"\n"]}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.h2,{id:"no-trace-ex",children:"No Trace (Ex)"}),"\n",(0,s.jsx)(n.p,{children:"At 3rd level, a Ninja learns to cover her tracks, remain hidden, and conceal her presence. The DC to track a Ninja using the Survival skill increases by +1. In addition, her training gives her a +1 insight bonus on Disguise skill checks and on opposed Stealth checks whenever she is stationary and does not take any action for at least 1 round. Every three levels thereafter, the increase to Survival DCs and the bonuses on Disguise and opposed Stealth checks increase by 1."}),"\n",(0,s.jsx)("u",{children:"This ability replaces Danger Sense."}),"\n",(0,s.jsx)(n.h2,{id:"master-ninja-tricks",children:"Master Ninja Tricks"}),"\n",(0,s.jsx)(n.p,{children:"At 10th level, and every two levels thereafter, a ninja can select one of the following master tricks in place of a ninja trick, in addition to general rogue advanced talents."}),"\n",(0,s.jsxs)(n.ul,{children:["\n",(0,s.jsxs)(n.li,{children:["\n",(0,s.jsx)(n.p,{children:"Acceleration of Form (Su): A ninja with this master trick can expend 1 ki point from her ki pool as a standard action to gain the benefits of displacement and haste for 1 round per 2 ninja levels."}),"\n"]}),"\n",(0,s.jsxs)(n.li,{children:["\n",(0,s.jsx)(n.p,{children:"All the Stars in the Sky (Ex): Certain master ninjas possess a seemingly limitless supply of their trusted weapons. Whenever a ninja with this master trick buys a set of 50 identical magic shuriken, she thereafter replenishes them at no cost and never runs out. This stock of magical shuriken can be upgraded as though it were a normal magic weapon, and shuriken upgraded this way likewise never run out."}),"\n"]}),"\n",(0,s.jsxs)(n.li,{children:["\n",(0,s.jsx)(n.p,{children:"Deadly Shuriken (Ex): As a full-round action, a ninja with this master trick can take careful aim and pool all of her attack potential into a single, deadly shuriken throw. When she does this, she throws a single shuriken at a single target, but makes as many attack rolls as she can, based on her base attack bonus. She makes the attack rolls in order from highest bonus to lowest, as if she were making a full attack. If any of the attack rolls hit the target, the attack hits. For each additional successful attack roll beyond the first, the ninja increases the damage by 1d6. Precision damage and extra damage from weapon special abilities (such as flaming) are added with damage modifiers and are not increased by this advanced talent. If one or more rolls are critical threats, she confirms the critical once using her highest base attack bonus \u20135. For each critical threat beyond the first, she reduces this penalty by 1 (to a maximum of 0)."}),"\n"]}),"\n",(0,s.jsxs)(n.li,{children:["\n",(0,s.jsx)(n.p,{children:"False Face (Su): Like oni who take mortal shapes to infiltrate society, some ninjas can mold their flesh to pass unsuspected. A ninja with this master trick gains the change shape (any Small or Medium humanoid, alter self) universal monster rule as long as she has at least 1 ki point."}),"\n"]}),"\n",(0,s.jsxs)(n.li,{children:["\n",(0,s.jsx)(n.p,{children:"Fractured Mirror (Su): By sending phantom selves across the battlefield, one may fight as many. When a ninja with this master trick uses the shadow clone ninja trick, she gains an additional clone for every 3 ninja levels she has, to a maximum of eight clones. In addition, while she has shadow clones deployed, the ninja can cause any number of her clones to split from herself as part of a move action. The shadow clones move up to the ninja\u2019s speed at her will each time she uses a move action to move. Shadow clones separated in this way are not considered part of the shadow clone trick until they return to the ninja\u2019s square, though they can still be destroyed while separated. Shadow clones separated from the ninja have an AC equal to the ninja\u2019s AC \u2013 5 and cannot take any actions, though they can provide flanking. Shadow clones do not occupy any space and a creature can freely enter a shadow clone\u2019s square. The ninja must have the shadow clone ninja trick to select this trick."}),"\n"]}),"\n",(0,s.jsxs)(n.li,{children:["\n",(0,s.jsx)(n.p,{children:"Ghost Step (Su): A ninja with this master trick can expend 1 ki point from her ki pool as a swift action to pass through walls as if she were a ghost. Until the end of her turn, she can pass through a wall or other surface that is up to 5 feet thick per level as if she were incorporeal. She must exit the solid material by the end of her turn."}),"\n"]}),"\n",(0,s.jsxs)(n.li,{children:["\n",(0,s.jsx)(n.p,{children:"Greater Ki Venom (Ex): A ninja with this master trick can further improve her ki venom. The ninja can spend 2 ki points to increase the damage die to a d8 or spend 2 ki points to change the ability damage dealt to Constitution damage. The ninja must have the ki venom ninja trick before selecting this trick."}),"\n"]}),"\n",(0,s.jsxs)(n.li,{children:["\n",(0,s.jsx)(n.p,{children:"Invisible Blade (Su): Whenever a ninja with this master trick uses the vanishing trick ninja trick, she is treated as if she were under the effects of greater invisibility. The ninja must have the vanishing trick ninja trick before selecting this ninja trick."}),"\n"]}),"\n",(0,s.jsxs)(n.li,{children:["\n",(0,s.jsx)(n.p,{children:"Kami Warden (Su): Ninjas can act as bodyguards as well as assassins or spies; some mystically emulate the relationship between kami and their wards when protecting their charges. A ninja with this master trick gains Bodyguard and In Harm's Way as bonus feats, ignoring their prerequisites. When using In Harm\u2019s Way to intercept an attack, the ninja can spend 1 ki point to gains DR 10/cold iron and resistance 10 to acid, electricity, and fire for that attack."}),"\n"]}),"\n",(0,s.jsxs)(n.li,{children:["\n",(0,s.jsx)(n.p,{children:"Kawarimi (Su): Once per day when a successful attack is made against a ninja with this ability, as an immediate action she can spend 1 ki point to attempt a Stealth check opposed by the attacker\u2019s Perception check. The ninja can attempt this check while being observed as long as she has cover or concealment (or an ability that allows her to attempt Stealth checks without cover or concealment). If she\u2019s successful, the opponent\u2019s attack hits an inanimate object that the attacker mistook for the ninja, and the ninja may move into an adjacent square and is hidden from the attacker."}),"\n"]}),"\n",(0,s.jsxs)(n.li,{children:["\n",(0,s.jsx)(n.p,{children:"Shadow Split (Su): This trick allows the ninja to create an illusory double of herself that moves away from her, allowing the ninja to create a distraction. When she uses this master trick, an illusory double appears and moves away from the ninja, heading in one direction. The double climbs walls, jumps pits, or simply passes through obstacles, moving at twice the ninja's speed in the direction indicated by the ninja when the ability is used. Its course cannot be changed. The double persists for 1 round per level of the ninja. Those who interact with the double receive a Will saving throw to recognize that it is fake. The DC of this save is 10 + 1/2 the ninja's level + the ninja's Charisma modifier. Each use of this ability uses up 1 ki point. The ninja must possess the shadow clone ninja trick before selecting this trick."}),"\n"]}),"\n",(0,s.jsxs)(n.li,{children:["\n",(0,s.jsx)(n.p,{children:"Spiritual Companion (Ex): While ninjas are accustomed to solitude, some form pacts with magical beings to seek aid and advice. A ninja with this master trick gains an improved familiar, treating her ninja level as her wizard level. The ninja can select any of the following as her familiar: calligraphy wyrm, pipefox, shikigami kami, or spirit oni. The ninja must have an alignment compatible with the chosen familiar."}),"\n"]}),"\n",(0,s.jsxs)(n.li,{children:["\n",(0,s.jsx)(n.p,{children:"Unarmed Combat Mastery: A ninja with this master trick deals damage with her unarmed strikes as if she were a monk of her ninja level \u20134. If the ninja has levels in monk, this ability stacks with monk levels to determine how much damage she can do with her unarmed strikes. A ninja must have the Unarmed Combatant feat before taking this trick."}),"\n"]}),"\n",(0,s.jsxs)(n.li,{children:["\n",(0,s.jsx)(n.p,{children:"Unbound Steps (Su): A ninja with this master trick can expend 1 ki point from her ki pool when she uses the Light Step ninja trick, allowing her to walk through the air. As part of her Light Step movement she can walk on air, rising or descending as she desires. She must end her move on a solid surface. The ninja must possess the light step ninja trick before selecting this trick."}),"\n"]}),"\n"]}),"\n",(0,s.jsx)(n.h2,{id:"hidden-master-su",children:"Hidden Master (Su)"}),"\n",(0,s.jsx)(n.p,{children:"At 20th level, a Ninja becomes a true master of her art. She can, as a standard action, cast greater invisibility on herself. While invisible in this way, she cannot be detected by any means, and not even invisibility purge, see invisibility, and true seeing can reveal her. She uses her Ninja level as her caster level for this ability. Using this ability consumes 3 ki points from her ki pool. In addition, whenever the Ninja deals sneak attack damage, she can sacrifice additional damage dice to apply a penalty to one ability score of the target equal to the number of dice sacrificed for 1 minute. This penalty does not stack with itself and cannot reduce an ability score below 1."}),"\n",(0,s.jsx)("u",{children:"This ability replaces Master Strike."})]})}function d(e={}){const{wrapper:n}={...(0,t.R)(),...e.components};return n?(0,s.jsx)(n,{...e,children:(0,s.jsx)(c,{...e})}):c(e)}},8453:(e,n,a)=>{a.d(n,{R:()=>r,x:()=>o});var i=a(6540);const s={},t=i.createContext(s);function r(e){const n=i.useContext(t);return i.useMemo((function(){return"function"==typeof e?e(n):{...n,...e}}),[n,e])}function o(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:r(e.components),i.createElement(t.Provider,{value:n},e.children)}}}]);